                tl = sum(buy.get(m, 0) + sel.get(m, 0) for m in mm)
                F["flow_delta_usd_" + ph], F["flow_imb_" + ph] = dl, (dl / tl if tl else None)
                F["flow_turn_x_" + ph] = tl / (qmed * len(mm)) if qmed else None
        sl = obwin(a_, b_)
        if sl:
